LESSONS=[]
KEYS={}
def lesson(n,date,title,objective,central,activation,core,oa,source):
    item=dict(n=n,id='nm2-2026-'+date[5:].replace('-',''),date=date,title=title,objective=objective,central=central,activation=activation,core=core,oa=oa,source=source,minutes=90,micro=[],texts=[],writing=[],model={})
    LESSONS.append(item);KEYS[item['id']]={};return item
def question(L,section,prompt,choices,skill='Interpretar',evidence='',reason='',concepts=None,errors=None):
    """La primera opción recibida es correcta; rota a una letra equilibrada por ID."""
    n=len(KEYS[L['id']])+1
    key_index=(n-1)%4
    # Exigir al menos un distractor tan extenso como la clave: evita una pista formal recurrente.
    if len(choices[0])>max(map(len,choices[1:])):
        raise ValueError(f'Clave más larga: {L["n"]}/{n}: {prompt}')
    indexed=[(choices[0],True,'')]+[(s,False,(errors or ['Confunde el recurso o la relación descrita.','Extiende el sentido sin evidencia suficiente.','Introduce información que el pasaje no permite sostener.'])[i]) for i,s in enumerate(choices[1:])]
    rotated=indexed[-key_index:]+indexed[:-key_index] if key_index else indexed
    q=dict(id=f'q{n:02}',text=prompt,options=[x[0] for x in rotated],skill=skill,concepts=concepts or [])
    KEYS[L['id']][q['id']]={'key':'ABCD'[key_index],'skill':skill,'evidence':evidence,'reason':reason,'distractors':{ 'ABCD'[i]:x[2] for i,x in enumerate(rotated) if not x[1]}}
    section.append(q)
    return q
def micro(L,prompt,choices,concepts,reason):
    return question(L,L['micro'],prompt,choices,evidence=prompt,reason=reason,concepts=concepts)
def text(L,title,genre,paragraphs):
    t=dict(id=f't{len(L["texts"])+1}',title=title,genre=genre,paragraphs=paragraphs,source='Texto original de Estudia CEST, creado para esta práctica. No corresponde a una prueba oficial.',questions=[]);L['texts'].append(t);return t

L=lesson(1,'2026-11-18','Quién cuenta y cómo se construye un relato','Interpretar narraciones relacionando la perspectiva del narrador, el tiempo y los indicios con el conflicto, y justificar la interpretación con evidencia textual.','¿Cómo cambia una historia según quién la cuenta y qué decide mostrar?','Si dos personas presencian el mismo hecho, ¿por qué pueden contarlo de manera diferente? Escriban una razón en el cuaderno y compártanla en parejas.', ['C001','C002','C003','C004','C005','C006','C007','C008','C015','C016','C020','C022','C025','C028','C033','C034'],['LE2M OA 03','LE2M OA 08'], 'TE 1M pp. 29–33, 48–49, 99–101; TE 2M pp. 36–37, 139–140, 259–261. GDD 1M T1 PDF 33 / p. impresa 22: reescritura del desenlace con otro narrador; adaptación CEST.')
L['model']={'sample':'Vi que Clara guardaba la llave. No supe por qué la escondía.','notice':'La voz dice «vi» y participa de la situación, pero reconoce un límite: «no supe».','reasoning':'Participar no basta para ser protagonista: lo narrado se concentra en Clara y la voz observa su conducta.','conclusion':'Es un narrador testigo. Podemos inferir reserva en Clara, pero todavía no sabemos su motivo.','check':'¿Qué información faltaría para afirmar que Clara actuó por culpa?'}
micro(L,'«Temía hablar; su hermano, lejos de allí, deseaba que lo hiciera». ¿Qué narrador permite conocer ambas interioridades?', ['Omnisciente.','Testigo de las dos escenas, sin conocer pensamientos.','Objetivo, limitado a registrar movimientos externos.','Protagonista que cuenta solo su propia experiencia.'],['C002','C009'],'La voz externa conoce pensamientos de dos personajes situados en lugares diferentes.')
micro(L,'«Lo acompañé al puente, pero nunca supe qué pensaba». ¿Qué narrador se reconoce?', ['Testigo.','Omnisciente que conoce los pensamientos de todos.','Objetivo que no participa en el mundo de la historia.','Protagonista que relata el centro de su propia aventura.'],['C005','C007'],'La voz participa y observa principalmente a otro personaje, sin acceder a su interioridad.')
micro(L,'«Abrí mi carta y decidí partir». Si el relato desarrolla las consecuencias de esa decisión para quien habla, ¿qué narrador predomina?', ['Protagonista.','Testigo de una decisión que tomó exclusivamente otra persona.','Omnisciente que comunica pensamientos de personajes distantes.','Objetivo externo que solo registra conductas observables.'],['C004'],'La voz cuenta su propia decisión central y sus consecuencias.')
micro(L,'«Dejó la carta, miró la puerta y salió». Sin datos de interioridad ni participación de la voz, ¿qué narrador se ejemplifica?', ['Objetivo.','Protagonista que cuenta directamente su propia salida.','Testigo que expresa su participación en los hechos.','Omnisciente que conoce los motivos secretos de todos.'],['C006','C008'],'Se presentan conductas observables desde una voz externa.')
micro(L,'Mientras espera el bus, un personaje recuerda brevemente una despedida de ayer. ¿Qué recurso aparece?', ['Flashback.','Prolepsis extensa que cuenta el futuro completo del personaje.','Historia paralela que cambia a otro mundo sin vínculo temporal.','Disposición ab ovo que conserva siempre el orden cronológico.'],['C025','C026'],'El presente se interrumpe con una retrospección breve.')
micro(L,'«Años después comprendería el valor de esa carta». ¿Qué alteración temporal contiene?', ['Prolepsis.','Analepsis que recupera acciones anteriores al presente del relato.','Caracterización directa que describe el aspecto físico del personaje.','Racconto que desarrolla extensamente una experiencia del pasado.'],['C028'],'La voz anticipa un acontecimiento posterior.')
micro(L,'El cuento comienza con la llegada final del viajero y después reconstruye su partida y recorrido. ¿Qué disposición presenta?', ['In extremas res.','In medias res, porque toda llegada pertenece a la mitad del viaje.','Ab ovo, porque el primer párrafo coincide con el inicio de la historia.','Cronología estricta, porque no retrocede desde el punto de inicio.'],['C032'],'El punto de partida del relato corresponde al final de la historia y luego se retrocede.')
micro(L,'«Era solidaria» y «compartía su comida con quienes no traían almuerzo» caracterizan de modo:', ['Directo e indirecto, respectivamente.','Indirecto y directo, porque una acción siempre nombra el rasgo.','Físico y físico, porque ambos enunciados describen su apariencia.','Omnisciente y objetivo, porque los enunciados clasifican narradores.'],['C016','C017'],'El primero nombra un rasgo; el segundo permite inferirlo a partir de una conducta.')
micro(L,'«Quería acusar el engaño, pero temía perjudicar a su amiga». ¿Qué tensión se manifiesta?', ['Un conflicto interno.','Un desenlace completamente resuelto por la narradora.','Un cambio físico del espacio donde ocurre la acción.','Una oposición externa entre dos grupos ya enfrentados.'],['C014'],'Se enfrentan deseos o valores dentro de un mismo personaje.')
micro(L,'«El puente cedió; por eso regresaron». ¿Qué relación introduce el conector?', ['Consecuencia.','Concesión que mantiene el regreso pese a un obstáculo contrario.','Contraste que opone el regreso a una acción sin relación causal.','Reformulación que sustituye una expresión por su equivalente.'],['C173','C013'],'El regreso se presenta como resultado del derrumbe.')
micro(L,'«La carta era escueta: solo decía “vuelve”». ¿Qué reemplazo conserva mejor el sentido de escueta?', ['Breve.','Imposible de entender por estar escrita en un idioma desconocido.','Afectuosa porque desarrolla extensamente los sentimientos.','Antigua porque describe hechos de muchos años atrás.'],['C208','C209'],'El contexto explicita la escasa extensión, no antigüedad ni incomprensibilidad.')
micro(L,'«La viajera entró. Ella dejó su bolso». ¿Qué función cumple ella?', ['Retomar a la viajera.','Introducir necesariamente a una segunda persona sin nombrarla.','Sustituir el bolso porque aparece en la misma oración.','Señalar el lugar del viaje mediante un conector temporal.'],['C162','C163'],'El pronombre mantiene el referente de la oración anterior.')
t=text(L,'La llave que no abría','Cuento',[
'Cuando la mujer dejó la llave sobre mi mesón, reconocí el hilo azul atado a su extremo. Mi padre hacía ese nudo para no confundir las llaves del taller con las de la casa. Yo llevaba doce años atendiendo la ferretería y nunca había visto entrar a esa mujer. Ella pidió una copia. Antes de encender la máquina, pregunté qué puerta abría. «Ninguna, por ahora», respondió.',
'El hilo me devolvió un recuerdo breve: mi padre, sentado junto a la radio, me enseñaba a distinguir dos llaves idénticas. «Lo importante no siempre está en los dientes», decía. Volví al mesón y noté que la mujer miraba la antigua foto del taller. Le pregunté si había conocido a mi padre. Asintió, pero no agregó nada. Supuse que había venido a cobrar una deuda; al comprobar que no llevaba papeles, me avergoncé un poco de mi rapidez para sospechar.',
'La máquina hizo la copia. Mientras limaba los bordes, la mujer contó que había vivido frente al taller y que, después de una crecida del río, mi padre le había prestado una pieza donde guardar sus muebles. «La puerta ya no existe», explicó. «Mi hermano no pudo despedirse de la casa. Quiero darle algo que podamos conservar los dos». Miré la llave de otro modo: ya no era una herramienta defectuosa, aunque no sirviera para abrir una cerradura.',
'Le entregué la copia y me negué a cobrar. La mujer dejó de todos modos unas monedas y se fue. Yo guardé la llave original que había quedado por descuido junto a la máquina. Afuera empezaba a llover. Salí hasta la vereda, pero la mujer había doblado la esquina. Cerré la mano sobre el hilo azul y avancé hacia ella. No sabía aún si le hablaría de mi padre o si bastaría con devolverle la llave.'
])
question(L,t['questions'],'¿Qué permite clasificar a la voz de este cuento como narrador protagonista?', ['Participa y relata cómo cambia su propia interpretación.','Conoce directamente los pensamientos secretos de la visitante.','Presenta la escena sin expresar recuerdos ni suposiciones.','Observa desde fuera una historia en la que nunca interviene.'],evidence='«Supuse»; «me avergoncé»; «Miré la llave de otro modo».',reason='El yo narra su participación y la transformación de su mirada, que organiza el cuento.',concepts=['C004','C009'],errors=['La voz formula suposiciones, pero no conoce la interioridad ajena.','Expresa recuerdos y juicios; no es un registro objetivo.','La voz atiende la ferretería, copia la llave y actúa al final.'])
question(L,t['questions'],'¿Qué función cumple el recuerdo del segundo párrafo?', ['Vincular el objeto con una enseñanza que adquiere otro sentido.','Demostrar que la visitante había robado la llave al padre.','Anticipar cómo el hermano utilizará la copia para abrir su casa.','Resolver la deuda que el narrador supone antes de escucharla.'],evidence='«Lo importante no siempre está en los dientes»; «ya no era una herramienta defectuosa».',reason='El recuerdo relaciona la enseñanza del padre con el valor afectivo que luego adquiere la llave.',concepts=['C026','C010'],errors=['No hay evidencia de robo.','El recuerdo va al pasado; la puerta ya no existe.','La deuda es una suposición del narrador, no un hecho comprobado.'])
question(L,t['questions'],'¿Qué cambio experimenta el narrador al escuchar a la visitante?', ['Pasa de sospechar una demanda a reconocer un valor afectivo.','Abandona la memoria de su padre para centrarse solo en vender.','Comprueba que la llave debe repararse para abrir la puerta perdida.','Descubre una deuda y decide pagarla mediante dos copias gratuitas.'],evidence='«Supuse que había venido a cobrar una deuda»; «Miré la llave de otro modo».',reason='La explicación de la visitante modifica una hipótesis apresurada y el significado atribuido al objeto.',concepts=['C018','C201','C205'],errors=['El recuerdo del padre se integra al cambio, no se abandona.','La puerta no existe; no se trata de reparar una función material.','La deuda no se confirma y solo se hizo una copia.'])
question(L,t['questions'],'¿Qué efecto produce el desenlace?', ['Deja abierta la forma que tomará el encuentro pendiente.','Confirma que el narrador nunca volvió a ver a la visitante.','Demuestra que la llave recuperó finalmente su utilidad original.','Asegura que el hermano rechazará el recuerdo de la casa perdida.'],skill='Evaluar',evidence='«No sabía aún si le hablaría de mi padre o si bastaría con devolverle la llave».',reason='La acción de avanzar ocurre, pero la conversación y su resultado quedan sin narrarse.',concepts=['C015'],errors=['El cuento termina antes del nuevo encuentro; no confirma que nunca ocurra.','No se vuelve a abrir la puerta inexistente.','No se presenta la reacción del hermano.'])
t=text(L,'La misma esquina','Relatos paralelos',[
'En la ciudad, Inés esperaba a su madre frente a una estación cerrada. Había llegado con una carpeta de documentos para solicitar una beca. Revisó la hora: aún faltaban veinte minutos. Su madre nunca le había contado por qué evitaba ese edificio. Inés conocía solo una frase repetida en casa: allí había aprendido a no esperar demasiado de las puertas cerradas.',
'Treinta años antes, en la misma esquina, Elena sostenía una carpeta bajo la lluvia. El funcionario había recibido su postulación y luego había señalado un cartel que exigía un certificado imposible de conseguir antes del cierre. Elena pensó en insistir, pero oyó detrás de ella la risa de dos personas y guardó la carpeta. Más tarde diría que el tren no había llegado a tiempo; era una explicación menos difícil que contar su vergüenza.',
'En la ciudad, Inés vio acercarse a su madre y levantó la mano. «Si falta algo, lo preguntamos juntas», dijo. Elena miró el edificio. No entraron: la oficina de becas se había trasladado a la biblioteca y ambas caminaron hacia allá. Antes de doblar, Elena pidió unos minutos. Se sentó con su hija en un banco y abrió, por primera vez, la carpeta de su propia historia.'
])
question(L,t['questions'],'¿Qué relación organiza las dos líneas temporales?', ['Dos postulaciones permiten contrastar aislamiento y acompañamiento.','Un mismo trámite se repite exactamente y termina con dos rechazos.','La hija recuerda una experiencia propia ocurrida treinta años antes.','La madre imagina un futuro en que su hija ocupará el cargo del funcionario.'],evidence='«Treinta años antes»; «lo preguntamos juntas».',reason='Se alternan situaciones distintas conectadas por el trámite, el lugar y una respuesta diferente ante la dificultad.',concepts=['C034','C022'],errors=['El segundo trámite no concluye en un rechazo y la oficina cambió de lugar.','La experiencia pasada corresponde a la madre.','El segundo párrafo reconstruye un pasado, no un futuro imaginado.'])
question(L,t['questions'],'¿Qué información permite afirmar que el narrador sabe más que Inés?', ['Conoce la vergüenza y la decisión pasada de Elena.','Describe una estación que Inés observa mientras espera.','Reproduce una frase que ambas han escuchado en casa.','Indica la hora que Inés puede consultar antes del encuentro.'],evidence='«era una explicación menos difícil que contar su vergüenza».',reason='Inés ignora el episodio; la voz externa accede a la interioridad de Elena y cuenta su motivo.',concepts=['C002','C010'],errors=['Describir lo que Inés ve no demuestra un conocimiento superior.','La frase familiar ya es conocida por la hija.','El tiempo de espera es accesible a Inés.'])
question(L,t['questions'],'En el cierre, ¿qué significa abrir «la carpeta de su propia historia»?', ['Comenzar a contar una experiencia que había mantenido en reserva.','Encontrar los certificados necesarios para obtener la beca de su hija.','Entregar al antiguo funcionario una nueva postulación completa.','Mostrar que los documentos antiguos sirven para el trámite actual.'],evidence='«por primera vez»; «no había contado»; «su propia historia».',reason='La expresión retoma la carpeta material y la usa para representar la narración de una experiencia silenciada.',concepts=['C010','C043','C206'],errors=['No se encuentran certificados para el trámite actual.','La oficina ya no funciona en ese lugar.','No se afirma validez actual de los documentos.'])
question(L,t['questions'],'¿Qué interpretación del espacio está mejor respaldada?', ['La esquina reúne un obstáculo pasado y la posibilidad de afrontarlo de otro modo.','La estación determina que todos los trámites de la familia terminen siempre igual.','El traslado de la oficina elimina cualquier necesidad de conversar sobre el pasado.','La biblioteca demuestra que las instituciones actuales nunca imponen requisitos.'],skill='Evaluar',evidence='La misma esquina conecta la soledad pasada con «lo preguntamos juntas».',reason='El lugar vincula las historias, pero el acompañamiento y la conversación abren otra respuesta posible.',concepts=['C020','C063'],errors=['El final no repite el rechazo ni presenta una ley inevitable.','La madre decide conversar precisamente al final.','Un caso no prueba una afirmación universal sobre las instituciones.'])
t=text(L,'Leer una versión no es conocerlo todo','Artículo informativo',[
'Una narración no entrega el mundo completo: selecciona una voz, un orden y ciertos detalles. Cuando un personaje cuenta que alguien «parecía culpable», informa una percepción. Para convertirla en una conclusión, el lector debe relacionarla con acciones, palabras y antecedentes. Una impresión puede orientar la lectura y también conducir a una equivocación.',
'Conviene distinguir tres operaciones. Primero, localizar lo explícito: qué se afirma y quién lo dice. Luego, inferir: qué relación permite proponer una explicación. Finalmente, evaluar: si esa explicación considera el conjunto y respeta sus límites. No se trata de adivinar lo que el autor pensó, sino de construir una interpretación que otros puedan examinar en el texto.',
'Por ejemplo, que una persona guarde una carta y evite mirar a otra permite inferir reserva o inquietud. No basta para asegurar un delito. Si después se explica que la carta contiene una despedida, la hipótesis debe revisarse. Releer no es repetir la primera impresión: es contrastarla con información nueva.',
'Un resumen conserva las acciones y relaciones centrales sin convertir posibilidades en certezas. Una reseña crítica añade una valoración de la obra y la fundamenta. En ambos casos, pronombres, conectores y párrafos deben permitir seguir los referentes y las ideas. Un texto claro hace visibles las relaciones; no resuelve por el lector todas las ambigüedades que la obra decidió conservar.'
])
question(L,t['questions'],'Según el artículo, ¿qué debe hacerse primero al examinar una afirmación narrativa?', ['Identificar qué se afirma y quién lo dice.','Decidir qué intención personal tuvo el autor real.','Eliminar las expresiones que puedan resultar ambiguas.','Elegir una conclusión antes de reunir antecedentes.'],skill='Localizar',evidence='«Primero, localizar lo explícito: qué se afirma y quién lo dice».',reason='El texto presenta esta operación antes de inferir y evaluar.',concepts=['C201','C200'])
question(L,t['questions'],'¿Por qué el ejemplo de la carta exige revisar la hipótesis inicial?', ['Una información posterior cambia el alcance de los indicios.','Todo gesto de inquietud demuestra que se ha cometido un delito.','Una carta de despedida impide que el personaje sienta preocupación.','La primera interpretación debe conservarse aunque surjan datos contrarios.'],evidence='«Si después se explica que la carta contiene una despedida, la hipótesis debe revisarse».',reason='Los indicios admiten interpretaciones que deben contrastarse con el desarrollo del relato.',concepts=['C205','C010'])
question(L,t['questions'],'¿Qué diferencia establece el texto entre resumen y reseña crítica?', ['La reseña incorpora una valoración fundamentada de la obra.','El resumen agrega opiniones que no necesitan evidencia textual.','La reseña sustituye las acciones por datos biográficos del autor.','El resumen transforma dudas del relato en hechos confirmados.'],evidence='«Una reseña crítica añade una valoración de la obra y la fundamenta».',reason='La valoración justificada distingue la reseña del resumen descrito.',concepts=['C152','C206'])
question(L,t['questions'],'¿Qué práctica contradice la propuesta del artículo?', ['Mantener una sospecha aunque otros datos la debiliten.','Distinguir las palabras del narrador de una afirmación del autor.','Usar un conector para aclarar cómo se relacionan dos acciones.','Reconocer que una interpretación puede conservar incertidumbre.'],skill='Evaluar',evidence='«Releer [...] es contrastarla con información nueva».',reason='Aferrarse a una sospecha impide el monitoreo y la revisión de la interpretación.',concepts=['C205','C206'])
