L=lesson(2,'2026-11-25','Cómo el lenguaje transforma lo que leemos','Interpretar poemas y relaciones literarias explicando el efecto de figuras, símbolos y tópicos mediante evidencia del texto.','¿Qué expresa un poema que una descripción literal no alcanza a decir?','Comparen «Estoy triste» con «La casa perdió su voz». Escriban qué agrega la segunda expresión y qué información todavía necesitan para interpretarla.', ['C036','C038','C039','C040','C042','C044','C045','C046','C047','C048','C049','C050','C051','C052','C053','C054','C055','C056','C057','C058','C059','C060','C061','C071','C072'], ['LE2M OA 04','LE2M OA 06','LE2M OA 08','LE2M OA 11'],'TE 1M pp. 217–220, 232–233, 246–247, 280–281, 299–301; TE 2M pp. 74, 77–78, 86–87, 99, 315–317. GDD 1M T2 PDF 30 / p. impresa 139: interpretación con ejemplos y relación entre tema, temple y actitud; adaptación CEST.')
L['model']={'sample':'La casa bosteza cuando vuelves.','notice':'Bostezar es una acción de un ser vivo, atribuida aquí a una casa.','reasoning':'El contexto de un regreso permite interpretar la casa como un espacio que despierta y recibe a alguien. No basta con nombrar personificación.','conclusion':'La personificación convierte el lugar en una presencia que participa del regreso. Otro contexto podría modificar ese efecto.','check':'¿Qué cambiaría si el verso dijera «La casa amenaza cuando vuelves»?'}
figures=[
 ('«Tus palabras son puentes». ¿Qué recurso identifica palabras y puentes?','Metáfora.',['Comparación explícita.','Personificación.','Aliteración.'],'C045','Identifica dos realidades por semejanza sin un nexo comparativo.'),
 ('«Tu voz es como una lámpara». ¿Qué recurso establece una semejanza explícita?','Comparación.',['Metáfora sin nexo.','Personificación.','Enumeración.'],'C046','El nexo como introduce una comparación.'),
 ('«La ciudad bosteza». ¿Qué figura atribuye una acción humana a la ciudad?','Personificación.',['Comparación explícita.','Aliteración reiterada.','Metonimia de autor.'],'C047','Una acción humana se atribuye a un espacio no humano.'),
 ('«Te esperé mil años». En una espera cotidiana, ¿qué figura intensifica su duración?','Hipérbole.',['Comparación explícita.','Metonimia de autor.','Aliteración.'],'C048','La duración se exagera para intensificar una experiencia.'),
 ('«Afuera ríen; adentro lloran». ¿Qué figura contrapone ideas?','Antítesis.',['Personificación.','Metonimia.','Comparación explícita.'],'C049','Se contraponen estados en dos construcciones, no en un único grupo de términos.'),
 ('«Un silencio ensordecedor». ¿Qué figura une términos opuestos en una expresión breve?','Oxímoron.',['Comparación explícita.','Personificación.','Enumeración.'],'C050','Silencio y ensordecedor se unen en una misma expresión paradójica.'),
 ('«Leí a Gabriela Mistral». ¿Qué figura usa a la autora para referirse a sus obras?','Metonimia.',['Comparación explícita.','Personificación.','Aliteración.'],'C051','La sustitución se basa en la relación autora-obra, no en semejanza.'),
 ('«Una voz azul». ¿Qué figura combina percepciones de sentidos distintos?','Sinestesia.',['Comparación explícita.','Personificación.','Metonimia.'],'C052','La voz pertenece a lo auditivo y azul a lo visual.'),
 ('«Aquí espero. Aquí recuerdo. Aquí vuelvo». ¿Qué figura repite una palabra al comienzo?','Anáfora.',['Comparación explícita.','Personificación.','Metonimia.'],'C053','La repetición inicial organiza la insistencia de las tres expresiones.'),
 ('«Susurra suave la seda». ¿Qué recurso se reconoce en la repetición de sonidos?','Aliteración.',['Comparación explícita.','Personificación del hablante.','Enumeración de lugares.'],'C054','La recurrencia sonora, especialmente de s, permite reconocer la aliteración.'),
 ('«Y llega y pregunta y espera». ¿Qué figura reitera la conjunción?','Polisíndeton.',['Comparación explícita.','Metonimia de autor.','Asíndeton.'],'C055','La repetición de y acumula las acciones con insistencia.'),
 ('«Corre, salta, tropieza, vuelve». ¿Qué figura omite conjunciones en la serie?','Asíndeton.',['Comparación explícita.','Polisíndeton.','Personificación.'],'C056','Las acciones se encadenan sin conjunciones.')]
for prompt,correct,distractors,cid,reason in figures: micro(L,prompt,[correct,*distractors],[cid],reason)
t=text(L,'La casa que aprende','Poema',[
'La casa se quedó sin voz\ncuando partiste.\nEl reloj masticaba la tarde\ny yo contaba sus migajas.',
'Aquí tu taza,\naquí la silla,\naquí la luz que no sabía\nsobre qué hombro descansar.',
'Hoy abrí las ventanas:\nentró una risa de la calle.\nNo era la tuya.\nDejé que se quedara.'
])
question(L,t['questions'],'¿Qué actitud lírica predomina en el poema?', ['Carmínica, por la expresión de una experiencia interior.','Apostrófica, porque todo el poema ordena acciones a un público.','Enunciativa, porque elimina las emociones de la voz que habla.','Informativa, porque entrega instrucciones verificables para una mudanza.'],evidence='«yo contaba»; «Dejé que se quedara».',reason='El poema desarrolla la vivencia subjetiva de una ausencia y una apertura; las otras opciones exageran o inventan su carácter.',concepts=['C040','C041'])
question(L,t['questions'],'¿Qué efecto produce «El reloj masticaba la tarde» en la primera estrofa?', ['Vuelve perceptible el desgaste de la espera.','Describe literalmente el mecanismo interior de un reloj.','Prueba que la persona ausente regresará durante la tarde.','Presenta una alegría que se mantiene sin cambios hasta el cierre.'],evidence='«se quedó sin voz»; «contaba sus migajas».',reason='La personificación y la imagen de las migajas relacionan el paso del tiempo con una experiencia de pérdida.',concepts=['C047','C042','C071'])
question(L,t['questions'],'¿Qué aporta la repetición de aquí en la segunda estrofa?', ['Insiste en las huellas cotidianas de la persona ausente.','Anuncia que se describirán tres ciudades diferentes.','Explica que taza, silla y luz pertenecen a nuevos visitantes.','Sustituye la expresión de ausencia por una instrucción de orden doméstico.'],evidence='«Aquí tu taza, / aquí la silla».',reason='La anáfora concentra la atención en objetos y espacios ligados a la ausencia.',concepts=['C053','C044'])
question(L,t['questions'],'¿Qué interpretación del cierre integra mejor el poema completo?', ['Aceptar otra risa abre una posibilidad sin borrar la ausencia.','El hablante olvida por completo a la persona que había partido.','La risa confirma el retorno físico de la persona a su antigua casa.','Abrir las ventanas restaura literalmente la voz de los objetos domésticos.'],skill='Evaluar',evidence='«No era la tuya. / Dejé que se quedara».',reason='Se distingue la nueva risa de la voz ausente y se acepta su presencia sin confundirlas.',concepts=['C041','C044','C063'])
t=text(L,'Antes de cerrar el día','Poema',[
'¿Dónde están las voces\nque llenaban esta plaza?\nEl polvo no responde\ny la fuente sigue en marcha.',
'No esperes que el verano\nprometa otra mañana:\ncomparte el pan de hoy,\nabre tu puerta y canta.',
'El tiempo cruza el puente\nsin devolver sus aguas.\nTu mano, mientras puede,\nque encuentre otra mano cercana.'
])
question(L,t['questions'],'¿Qué tópico se reconoce principalmente en la pregunta de la primera estrofa?', ['Ubi sunt.','Carpe diem, porque ordena disfrutar un encuentro que ya ocurre.','Vita somnium, porque declara que la plaza es solo un sueño.','Contemptus mundi, porque exige abandonar todos los bienes materiales.'],evidence='«¿Dónde están las voces / que llenaban esta plaza?».',reason='La pregunta evoca presencias desaparecidas.',concepts=['C076'])
question(L,t['questions'],'¿Qué relación establece la segunda estrofa con la fugacidad del tiempo?', ['Invita a compartir el presente sin asegurar un mañana.','Promete que el verano siguiente repetirá los mismos encuentros.','Rechaza el valor de las relaciones humanas por ser pasajeras.','Defiende esperar inmóvil hasta que vuelvan las voces del pasado.'],evidence='«No esperes»; «comparte el pan de hoy».',reason='La exhortación vincula la incertidumbre del mañana con el aprovechamiento del presente.',concepts=['C072','C071','C039'])
question(L,t['questions'],'¿Cómo funciona el puente en la tercera estrofa?', ['Concreta el paso irreversible del tiempo.','Informa dónde y cuándo se construyó una obra pública.','Permite que las aguas regresen a su lugar de origen.','Demuestra que la plaza se encuentra abandonada desde una inundación.'],evidence='«El tiempo cruza el puente / sin devolver sus aguas».',reason='La imagen vincula tránsito y no retorno; no entrega datos documentales sobre un puente real.',concepts=['C045','C071'])
question(L,t['questions'],'¿Qué afirmación sobre los dos poemas resulta mejor sustentada?', ['Ambos enfrentan una pérdida y proponen una apertura hacia otros.','Ambos garantizan que el pasado regresará si se conservan objetos.','El primero entrega información objetiva y el segundo elimina toda emoción.','El segundo niega el paso del tiempo y el primero confirma que no existe.'],skill='Evaluar',evidence='«Dejé que se quedara»; «que encuentre otra mano cercana».',reason='La aceptación de otra risa y la búsqueda de una mano relacionan pérdida y apertura sin prometer restitución del pasado.',concepts=['C063','C080','C008'])
t=text(L,'Una forma antigua, nuevas preguntas','Artículo de contexto literario',[
'Reconocer un recurso literario exige observar cómo funciona en una obra. Una metáfora no expresa siempre tristeza ni una repetición significa siempre alegría. El lector relaciona las palabras, su posición y el conjunto del texto. La etiqueta ayuda a describir una decisión expresiva; la interpretación explica para qué sirve en ese caso.',
'También las formas y los tópicos viajan entre épocas. El soneto tradicional organiza catorce versos endecasílabos en dos cuartetos y dos tercetos. Su distribución puede ordenar una tensión y una respuesta, pero no obliga a todos los poemas a pensar lo mismo. Para reconocerlo no basta contar versos: hay que observar su organización y revisar su métrica.',
'En obras del Barroco español son frecuentes preocupaciones por la fugacidad, el desengaño y la relación entre apariencia y realidad. Siglos después, un poema actual puede retomar carpe diem o ubi sunt. Esa coincidencia no convierte automáticamente al poema en una obra barroca: permite examinar una relación con una tradición y los cambios de sentido que introduce el nuevo contexto.',
'Del mismo modo, el Romanticismo valoró la subjetividad, la libertad y la originalidad, pero una voz que dice yo no basta para clasificar una obra como romántica. La interpretación requiere otros rasgos y antecedentes. Una alusión o una parodia puede transformar una obra anterior sin reproducirla: comprender esa relación exige leer ambas y distinguir semejanzas, diferencias y efectos.',
'Una reseña crítica puede explicar estas decisiones con evidencia. En vez de afirmar que un poema es bonito porque tiene metáforas, puede mostrar cómo una casa personificada expresa una ausencia y cómo el final modifica ese estado. La valoración se vuelve discutible y examinable porque ofrece razones concretas.'
])
question(L,t['questions'],'Según el texto, ¿qué caracteriza al soneto tradicional?', ['Catorce versos endecasílabos en dos cuartetos y dos tercetos.','Catorce versos de cualquier medida, distribuidos siempre en una sola estrofa.','Doce versos en tres estrofas que mantienen necesariamente una misma emoción.','Una repetición inicial que garantiza por sí misma una clasificación barroca.'],skill='Localizar',evidence='Segundo párrafo: catorce versos endecasílabos, dos cuartetos y dos tercetos.',reason='La forma se describe mediante número, métrica y organización; las otras opciones eliminan o alteran condiciones.',concepts=['C061','C062'])
question(L,t['questions'],'¿Por qué un tópico antiguo no basta para clasificar un poema actual como barroco?', ['Un recurso compartido puede adquirir otro sentido en un nuevo contexto.','Todos los tópicos antiguos desaparecieron antes de la literatura contemporánea.','La clasificación de una obra depende exclusivamente de la cantidad de versos.','Un poema actual que retoma una tradición necesariamente plagia la obra anterior.'],evidence='«permite examinar una relación con una tradición y los cambios de sentido».',reason='El texto distingue diálogo con una tradición de pertenencia histórica automática.',concepts=['C063','C065','C077'])
question(L,t['questions'],'¿Qué relación establece el último párrafo entre valoración y evidencia?', ['La evidencia permite discutir las razones de una valoración.','La valoración impide explicar los efectos de un recurso literario.','La presencia de metáforas demuestra por sí sola la calidad de cualquier obra.','Los lectores deben aceptar una opinión si fue escrita en una reseña publicada.'],evidence='«ofrece razones concretas».',reason='Analizar decisiones y sus efectos convierte la valoración en una propuesta fundamentada.',concepts=['C152','C111'])
question(L,t['questions'],'¿Qué comentario aplica mejor el criterio de interpretación propuesto?', ['La nueva risa cambia el cierre porque abre la casa a otra presencia.','El poema es romántico únicamente porque su hablante utiliza la primera persona.','La casa está triste porque todas las personificaciones expresan siempre tristeza.','El poema es mejor que otros porque contiene una cantidad superior de figuras.'],skill='Evaluar',evidence='Primer y último párrafos: interpretar función en contexto y justificar con ejemplos.',reason='La primera opción relaciona un elemento concreto con su efecto en el conjunto; las otras sustituyen análisis por reglas generales sin respaldo.',concepts=['C047','C063'])
L['writing']=[
 {'id':'w1','prompt':'Escriban dos oraciones sobre una espera: una con metáfora y otra con comparación. Después expliquen en 2 líneas qué relación construyeron.','criteria':'Identificación sin nexo frente a semejanza explícita; explicación coherente con ejemplos propios.','support':'Contraste «la espera es un desierto» con «la espera es como un desierto»; cambie después el ejemplo.'},
 {'id':'w2','prompt':'Elijan una figura de «La casa que aprende». Citen el verso y expliquen su efecto en 3–4 líneas. Relaciónenlo con el cambio del final.','criteria':'Recurso bien identificado, cita pertinente, efecto situado y relación con el cierre; admite lecturas justificadas.','support':'Pregunte qué comunica el verso sobre la ausencia y qué cambia con la nueva risa.'},
 {'id':'w3','prompt':'Reescriban la segunda estrofa de «Antes de cerrar el día» en 4 versos, conservando carpe diem y cambiando sus imágenes. Expliquen en una oración cómo conservaron el tópico.','criteria':'Exhorta a aprovechar el presente, utiliza imágenes propias y justifica la relación; no exige rima.','support':'No basta escribir disfruta: pida mostrar una decisión presente ante la fugacidad.'}]

L=lesson(3,'2026-12-02','Qué razones sostienen una opinión','Evaluar argumentos y recursos persuasivos, distinguiendo razonamientos y falacias, y fundamentar una postura con evidencia pertinente.','¿Qué hace que una razón sostenga realmente una opinión?','Comparen «Debemos abrir porque sería maravilloso» con «Debemos abrir porque el horario actual impide retirar libros a quienes viajan temprano». Escriban qué habría que comprobar para evaluar la segunda razón.', ['C104','C105','C108','C109','C110','C111','C112','C113','C114','C115','C116','C117','C118','C119','C120','C121','C122','C123','C124','C128','C129','C130'], ['LE2M OA 09','LE2M OA 14'], 'TE 1M pp. 126–128, 330–331, 356–361; TE 2M pp. 148–151, 162–167, 268–269, 278–281. Actividades y textos originales CEST.')
L['model']={'sample':'Dos personas dijeron que no usan la biblioteca; por eso nadie necesita que abra.','notice':'La conclusión habla de nadie; el respaldo solo considera a dos personas.','reasoning':'Falta comprobar cuántas personas integran el grupo y si esos dos casos lo representan. El problema no se resuelve repitiendo la conclusión con más seguridad.','conclusion':'Es una generalización apresurada. Podría reformularse: dos personas consultadas no la usan; falta investigar las necesidades del conjunto.','check':'¿Qué información permitiría ampliar responsablemente el alcance de la conclusión?'}
micro(L,'¿Cuál es una tesis sobre una decisión escolar?', ['La biblioteca debería abrir durante el recreo.','La biblioteca tiene mesas, sillas y una entrada ubicada al norte.','El horario impreso indica que la biblioteca abre a las ocho.','El registro cuenta ciento veinte préstamos durante septiembre.'],['C104'],'Propone una postura discutible, a diferencia de los enunciados descriptivos o verificables.')
micro(L,'Se consulta una muestra representativa y se formula una conclusión acotada sobre el curso. ¿Qué razonamiento predomina?', ['Generalización.','Analogía entre casos de instituciones muy diferentes.','Autoridad basada solo en el prestigio de una celebridad.','Amenaza que reemplaza las razones de una propuesta.'],['C112'],'La inferencia va de casos pertinentes hacia una conclusión sobre un conjunto delimitado.')
micro(L,'«La filtración moja los libros; reparar el techo evitaría ese daño». ¿Qué relación fundamenta la propuesta?', ['Causa y consecuencia.','Semejanza entre dos bibliotecas sin considerar sus condiciones.','Prestigio de una persona que no conoce el problema descrito.','Ataque a la personalidad de quien se opone a la reparación.'],['C113'],'La propuesta se fundamenta en una relación causal entre filtración y daño.')
micro(L,'«Las solicitudes pendientes son un indicio de demanda de préstamos». ¿Qué razonamiento se usa?', ['Por signos.','Por analogía con una biblioteca de otro país no descrita.','Por autoridad fundada en el cargo de quien hace la afirmación.','Por amenaza para obligar a todos a solicitar libros nuevos.'],['C114'],'Una señal observable se usa para inferir una condición, con el alcance que permitan los datos.')
micro(L,'Se cita a una especialista en conservación para fundamentar cómo proteger los libros de la humedad. ¿Qué razonamiento aparece?', ['Por autoridad pertinente.','Por generalización de una sola experiencia a todos los temas.','Por analogía entre hechos que no se describen como semejantes.','Por ataque personal a quien administra la biblioteca escolar.'],['C115'],'Se apela a competencia relevante para el asunto, no solo a fama o poder.')
micro(L,'Dos bibliotecas semejantes en tamaño y personal se comparan para proponer un horario. ¿Qué razonamiento aparece?', ['Por analogía.','Por amenaza a los estudiantes que prefieren otro horario.','Por signos que se consideran pruebas absolutas de cualquier conclusión.','Por autoridad de una persona ajena a la gestión de las bibliotecas.'],['C116'],'La propuesta traslada una relación entre casos cuyas semejanzas pertinentes deben examinarse.')
micro(L,'«Dos alumnos devolvieron tarde: todos los jóvenes son irresponsables». ¿Qué falla presenta?', ['Generalización apresurada.','Analogía respaldada por condiciones equivalentes y suficientes.','Refutación que considera y responde una razón contraria concreta.','Argumentación que limita su conclusión a los dos casos observados.'],['C120'],'La conclusión excede los casos y convierte una conducta en una característica universal.')
micro(L,'«Un cantante famoso lo recomienda; por eso este tratamiento es eficaz». ¿Qué falacia aparece si esa es la única razón?', ['Ad verecundiam.','Razonamiento causal respaldado por estudios del tratamiento.','Analogía que compara resultados de dos experimentos equivalentes.','Generalización acotada a pacientes estudiados con procedimientos claros.'],['C121'],'La fama del cantante no acredita competencia ni evidencia de eficacia en salud.')
micro(L,'«Mi propuesta es correcta: si no la apoyas, te sacaré del grupo». ¿Qué falacia aparece?', ['Ad baculum.','Razonamiento por signos que reconoce la incertidumbre del indicio.','Argumento de autoridad pertinente en el tema que se está discutiendo.','Refutación que contesta con datos las razones del otro participante.'],['C122'],'La amenaza pretende sustituir la evaluación de las razones.')
micro(L,'«El edificio tiene ventanas nuevas; por eso sus libros son los más leídos». ¿Qué falla presenta?', ['Non sequitur.','Relación causal comprobada por registros de lectura y uso del espacio.','Analogía entre dos colecciones cuyos lectores y tamaños se compararon.','Generalización de datos suficientes sobre préstamos durante varios años.'],['C123'],'La conclusión sobre lectura no se desprende de la premisa sobre ventanas.')
micro(L,'«No escuches su propuesta: ayer se equivocó en matemáticas». ¿Qué falacia aparece?', ['Ad hominem.','Refutación que muestra un error en los datos de la propuesta del horario.','Argumento causal que prueba por qué el horario afecta los préstamos.','Analogía entre distintas soluciones con condiciones equivalentes.'],['C124'],'Se descalifica a la persona en vez de examinar sus razones sobre el asunto.')
micro(L,'¿Qué enunciado expresa una valoración?', ['El horario actual es injusto.','El horario impreso señala atención desde las ocho hasta las doce.','El registro del lunes contiene treinta solicitudes de préstamo.','La puerta tiene un cartel donde se indica la hora de cierre.'],['C108','C130'],'Injusto formula un juicio; las otras afirmaciones son contrastables con registros u observación.')
t=text(L,'Abrir la puerta no basta','Columna de opinión',[
'Propongo que la biblioteca escolar abra durante dos recreos a la semana, con un período de prueba y una revisión posterior. La propuesta no nace de creer que cualquier apertura produce lectores. Nace de una dificultad concreta: algunos estudiantes salen hacia el bus apenas terminan las clases y no alcanzan a retirar libros en el horario de la tarde.',
'Una consulta voluntaria reunió respuestas de treinta estudiantes. Dieciocho dijeron que usarían el recreo para pedir libros. El dato muestra interés entre quienes respondieron, pero no permite afirmar que dieciocho de cada treinta estudiantes del colegio harán lo mismo. Quienes disfrutan leer pudieron tener más disposición a participar. Por eso conviene combinar esa consulta con registros de préstamo y preguntas a quienes hoy no usan la biblioteca.',
'Se objeta que abrir más tiempo aumenta la carga de trabajo de la encargada. Es una preocupación válida. La propuesta requiere acordar un turno autorizado y acotado; los estudiantes podrían ordenar una fila o difundir el horario, pero no reemplazar funciones que necesitan responsabilidad adulta. Si no existe personal disponible, habría que modificar el plan y no esconder ese límite detrás del entusiasmo.',
'También importa qué ocurre dentro. Una biblioteca es un puente, pero un puente necesita dos orillas accesibles: un horario útil y una colección que invite a entrar. Abrir una sala sin libros pertinentes puede cambiar el registro de puertas abiertas sin mejorar el acceso a la lectura. Revisar preferencias no significa comprar solo lo que ya se conoce; significa encontrar una conversación posible entre nuevos textos y experiencias de los lectores.',
'Al terminar el mes de prueba, se podrían comparar préstamos, consultas y dificultades de funcionamiento. Un aumento no demostraría por sí solo que el horario causó una mejora permanente: podrían influir una campaña simultánea o una lectura obligatoria. La decisión sería más sólida si se documentan esas condiciones y se escucha a usuarios y no usuarios.',
'¿De qué sirve defender el acceso si no examinamos quién puede entrar y para qué? La pregunta no exige aprobar mi horario exacto. Invita a que cualquier alternativa explique qué barrera atiende, con qué recursos y cómo sabremos si funcionó. Una puerta abierta es un comienzo; sostener el acceso requiere razones que puedan revisarse.'
])
question(L,t['questions'],'¿Cuál es la tesis central de la columna?', ['Probar una apertura acotada y evaluarla según necesidades y recursos.','Abrir todos los días sin condiciones porque una sala abierta siempre forma lectores.','Reemplazar a la encargada por estudiantes para reducir permanentemente los costos.','Mantener el horario actual hasta que toda la comunidad responda la misma encuesta.'],evidence='Primer párrafo: «dos recreos a la semana, con un período de prueba».',reason='La postura propone una intervención limitada y revisable, no una apertura universal sin recursos.',concepts=['C104','C153'])
question(L,t['questions'],'¿Por qué el autor limita la conclusión que puede extraerse de la consulta?', ['La participación voluntaria puede reunir a personas con mayor interés previo.','La cantidad de respuestas demuestra que ningún estudiante necesita libros.','Las encuestas impiden conocer cualquier preferencia de las personas consultadas.','Los registros de préstamo prueban que todos los estudiantes ya usan la biblioteca.'],evidence='«Quienes disfrutan leer pudieron tener más disposición a participar».',reason='Se reconoce un posible sesgo de selección y se limita la generalización.',concepts=['C112','C120','C111'])
question(L,t['questions'],'¿Cómo responde la columna a la objeción sobre la carga laboral?', ['Reconoce el límite y condiciona el plan a un turno autorizado.','Niega que exista trabajo adicional porque la encuesta muestra interés lector.','Descalifica a la encargada por impedir una propuesta de los estudiantes.','Asegura que cualquier estudiante puede reemplazar todas las funciones adultas.'],evidence='«Si no existe personal disponible, habría que modificar el plan».',reason='La refutación no niega el problema: incorpora una condición que permite discutir la viabilidad.',concepts=['C118','C117'])
question(L,t['questions'],'¿Qué función cumple la metáfora del puente?', ['Relacionar horario y colección como condiciones conjuntas del acceso.','Demostrar que la biblioteca necesita construir una pasarela física sobre un río.','Sustituir la necesidad de recursos por una imagen que confirma cualquier propuesta.','Probar que abrir la puerta basta para mejorar de manera permanente los préstamos.'],evidence='«dos orillas accesibles: un horario útil y una colección».',reason='La imagen articula dos condiciones; no reemplaza las razones ni plantea una obra material.',concepts=['C045','C131'])
t=text(L,'Dos mensajes para una misma discusión','Intercambio argumentativo',[
'Mensaje de Tomás: «No debemos cambiar nada. El mes pasado vinieron dos cursos a la biblioteca y dejaron libros fuera de lugar. Ya sabemos cómo son todos los estudiantes. Además, quienes proponen abrir durante el recreo suelen hablar mucho en clases; no veo por qué escuchar su proyecto».',
'Respuesta de Amalia: «Ordenar los libros es un problema que debe resolverse, pero esos dos episodios no describen a todo el colegio. Propongo revisar cuántas veces ocurrió y en qué condiciones. Que una persona converse en clase tampoco permite decidir si el horario propuesto es viable. Podemos pedirle que explique su plan y discutir esas razones».',
'Tomás agrega: «En otra escuela resultó bien un turno de recreo». Amalia responde: «Ese caso puede orientarnos, si conocemos su personal y cuántos usuarios atiende. Si sus condiciones son distintas, habría que adaptar la idea. Comparemos lo relevante antes de trasladar su resultado a nuestra escuela».',
'Ambos acuerdan preparar una tabla con el problema que intenta resolver cada propuesta, recursos disponibles y evidencia que falta. Todavía no eligen un horario. La discusión cambió: en lugar de atribuir cualidades a un grupo, comienzan a examinar decisiones concretas.'
])
question(L,t['questions'],'¿Qué problema comparten las dos primeras razones de Tomás?', ['Desplazan la evaluación del plan hacia juicios sobre personas.','Analizan las condiciones de la otra escuela antes de aceptar una analogía.','Reconocen que el orden de los libros exige investigar las circunstancias.','Presentan datos representativos y suficientes de toda la comunidad escolar.'],evidence='«cómo son todos»; «suelen hablar mucho».',reason='Una generalización sobre estudiantes y una descalificación personal sustituyen el examen del proyecto.',concepts=['C120','C124'])
question(L,t['questions'],'¿Qué distingue la respuesta de Amalia de una defensa incondicional de la apertura?', ['Admite el problema y pide revisar datos y viabilidad.','Rechaza cualquier antecedente porque proviene de Tomás.','Asegura que la apertura debe aprobarse antes de reunir información.','Presenta una amenaza para obligar al otro participante a apoyar el plan.'],evidence='«es un problema que debe resolverse»; «discutir esas razones».',reason='Amalia separa reconocer un problema de aceptar conclusiones defectuosas sobre personas o soluciones.',concepts=['C118','C109','C110'])
question(L,t['questions'],'¿Qué condición exige Amalia para usar la experiencia de otra escuela?', ['Comparar personal y usuarios antes de transferir el resultado.','Comprobar únicamente que ambas escuelas tienen bibliotecas con puertas.','Elegir la escuela más conocida aunque no se disponga de datos sobre su funcionamiento.','Aplicar el mismo horario sin cambios para evitar que la comparación resulte distinta.'],evidence='«si conocemos su personal y cuántos usuarios atiende».',reason='La analogía requiere semejanzas pertinentes para la decisión, no una coincidencia superficial.',concepts=['C116'])
question(L,t['questions'],'¿Qué evaluación del acuerdo final está mejor respaldada?', ['Mejora el procedimiento de discusión sin resolver todavía el horario.','Confirma que la propuesta de Tomás fue aprobada por toda la escuela.','Demuestra que una tabla elimina cualquier necesidad de investigar el problema.','Asegura que la otra escuela debe cambiar su horario para igualar sus condiciones.'],skill='Evaluar',evidence='«Todavía no eligen un horario»; «evidencia que falta».',reason='El acuerdo ordena la indagación y la comparación, pero no constituye la decisión final.',concepts=['C107','C110','C111'])
t=text(L,'Una palabra puede inclinar la balanza','Ensayo breve',[
'Dos titulares pueden describir un mismo acuerdo: «La comunidad solicita ampliar un horario» y «Un grupo exige privilegios de atención». Ninguno necesita cambiar la cantidad de firmantes para orientar una mirada diferente. Solicitar y exigir, comunidad y grupo, ampliar un horario y obtener privilegios no construyen la misma representación de los participantes ni de sus motivos.',
'El léxico valorativo no vuelve falso a un texto por sí solo. Una columna puede defender una postura y expresarla con claridad. El problema aparece cuando la valoración se presenta como si fuera un dato comprobado o cuando reemplaza el examen de razones. Llamar privilegio a una petición exige explicar qué ventaja desigual se obtendría y respecto de quién.',
'Una pregunta retórica también puede dirigir la atención: «¿Quién podría estar contra la lectura?». La frase busca adhesión, pero discutir el horario de una sala no equivale a oponerse a leer. Una reformulación más justa sería preguntar qué alternativa permite acceder a libros sin ignorar restricciones de personal y seguridad.',
'Evaluar no consiste en borrar toda emoción. Un testimonio puede hacer visible una dificultad que los números no muestran. Conviene examinar qué demuestra ese caso, qué no permite generalizar y qué otros antecedentes se necesitan. La pregunta clave es si el recurso acerca una razón o evita que la revisemos.'
])
question(L,t['questions'],'¿Qué contraste ilustra el primer párrafo?', ['La elección de palabras puede valorar de modo distinto un mismo acuerdo.','Cambiar de titular obliga siempre a alterar la cantidad real de firmantes.','Todo grupo que pide un horario busca necesariamente obtener un privilegio.','Una noticia pierde cualquier contenido informativo si utiliza un sustantivo colectivo.'],evidence='«no construyen la misma representación».',reason='El contraste muestra encuadres valorativos distintos sin exigir cambiar un dato numérico.',concepts=['C130','C144'])
question(L,t['questions'],'Según el ensayo, ¿qué exige presentar una petición como privilegio?', ['Explicar la ventaja desigual que supuestamente produciría.','Eliminar cualquier dato sobre las personas que realizan la petición.','Demostrar que todos los firmantes expresan exactamente la misma emoción.','Sustituir las razones del acuerdo por una pregunta que impida discutirlo.'],skill='Localizar',evidence='«qué ventaja desigual se obtendría y respecto de quién».',reason='El texto pide fundamentar la valoración en una relación concreta de desigualdad.',concepts=['C130','C109'])
question(L,t['questions'],'¿Por qué se cuestiona «¿Quién podría estar contra la lectura?»?', ['Equipara discutir un horario con rechazar la lectura.','Pide conocer restricciones y alternativas antes de decidir un horario.','Introduce una cita directa que identifica una fuente verificable del acuerdo.','Invita a comparar con precisión las distintas necesidades de acceso al recinto.'],evidence='«discutir el horario [...] no equivale a oponerse a leer».',reason='La pregunta desplaza el asunto y dificulta considerar objeciones legítimas.',concepts=['C126','C110','C123'])
question(L,t['questions'],'¿Cuál es el criterio final para evaluar un recurso persuasivo?', ['Examinar si permite comprender o evita revisar una razón.','Rechazarlo en cuanto incluya cualquier emoción de un participante.','Aceptarlo si coincide con la postura que el lector tenía antes de leer.','Considerarlo válido siempre que aparezca en una columna firmada por su autor.'],skill='Evaluar',evidence='«si el recurso acerca una razón o evita que la revisemos».',reason='El criterio relaciona la función persuasiva con el examen de fundamentos y límites.',concepts=['C131','C106','C111'])
L['writing']=[
 {'id':'w1','prompt':'Reescriban la primera intervención de Tomás en 3–4 líneas: conserven el problema del orden, retiren las falacias y formulen una razón que pueda investigarse.','criteria':'No generaliza a todo el alumnado ni ataca a personas; conserva el problema y pide evidencia pertinente.','support':'Pregunte qué se observó realmente y qué conclusión permiten solo esos casos.'},
 {'id':'w2','prompt':'Redacten una tesis propia sobre un horario de biblioteca y dos argumentos en 5–6 líneas. Señalen qué fuente necesitarían para respaldar cada razón; no inventen cifras.','criteria':'Tesis discutible; dos razones relevantes; fuentes apropiadas y distinción entre dato disponible y requerido.','support':'Una razón sobre transporte necesita horarios o testimonios pertinentes, no una celebridad.'},
 {'id':'w3','prompt':'Escriban una objeción posible a su propuesta y respóndanla en 3–4 líneas. Revisen un conector y una expresión valorativa para que la respuesta sea clara y respetuosa.','criteria':'Objeción pertinente, respuesta razonada, cohesión y trato respetuoso; admite distintas posturas.','support':'Pida responder el costo o la limitación planteada, no cambiar de tema ni descalificar.'}]

L=lesson(4,'2026-12-09','Cómo una escena y un mensaje orientan nuestra mirada','Interpretar conflictos dramáticos y evaluar mensajes de los medios, explicando cómo sus recursos y fuentes construyen sentido y credibilidad.','¿Cómo influyen las palabras, la puesta en escena y la selección de datos en lo que creemos?','Lean «La sala estaba vacía». Propongan dos contextos que cambien su interpretación. ¿Basta esa frase para afirmar que a nadie le interesa la actividad?', ['C084','C085','C086','C087','C088','C091','C092','C093','C094','C096','C097','C098','C099','C100','C142','C143','C144','C145','C146','C147'], ['LE2M OA 05','LE2M OA 10','LE2M OA 24'], 'TE 1M pp. 154–155, 169–171, 188, 351–355; TE 2M pp. 96–99, 199–201, 208–209, 340–363. Textos, mensajes, datos y actividades recreados por CEST para lectura crítica.')
L['model']={'sample':'Un afiche muestra una sala vacía y dice: «A nadie le interesa leer». El pie indica: foto tomada antes de abrir.','notice':'La imagen registra un momento específico: antes de la apertura.','reasoning':'Una sala vacía en ese instante no informa cuántas personas van durante el horario de atención ni por qué no están en la foto.','conclusion':'El mensaje generaliza más allá de su evidencia. Para evaluarlo se necesitan horario, momento de captura y registros de uso.','check':'¿Qué fotografía o registro adicional sería pertinente y qué seguiría sin demostrar?'}
micro(L,'En una obra, un personaje quiere abrir una sala y otro se opone por una filtración. ¿Qué elemento organiza la acción?', ['Conflicto dramático.','Desenlace ya resuelto que elimina cualquier oposición.','Narrador protagonista que describe sus recuerdos.','Rima consonante entre las palabras de ambos personajes.'],['C085'],'Hay oposición de fuerzas y motivos que impulsa la acción.')
micro(L,'«(Baja la voz y mira hacia la puerta)». ¿Qué elemento del texto dramático es?', ['Acotación.','Aparte que todos los personajes escuchan como conversación.','Verso que expresa la opinión de un narrador omnisciente.','Titular informativo que documenta un hecho fuera de la obra.'],['C095'],'La indicación orienta actuación y representación; no es un parlamento pronunciado.')
micro(L,'Un personaje dice algo al público que los demás personajes, por convención, no oyen. ¿Qué recurso usa?', ['Aparte.','Diálogo donde todos los personajes responden a la intervención.','Cita periodística que identifica una entrevista realizada fuera de escena.','Acotación que únicamente describe la iluminación del escenario.'],['C094'],'El público oye una intervención que otros personajes no deben oír en la ficción escénica.')
micro(L,'Una intervención extensa desarrolla en voz alta las dudas de un personaje sin intercambio inmediato. ¿Qué forma adopta?', ['Monólogo.','Diálogo entre varios personajes con respuestas alternadas.','Titular que resume datos y cita un registro de asistencia.','Narración objetiva externa que evita toda expresión de pensamiento.'],['C093'],'El personaje desarrolla su pensamiento mediante una intervención sin intercambio inmediato.')
micro(L,'La luz disminuye, se oyen golpes y los personajes hablan entrecortadamente. En conjunto, estos recursos construyen:', ['Una atmósfera de tensión.','Un narrador omnisciente que informa el pensamiento de todos.','Una demostración documental de que existe un peligro real fuera de la ficción.','Un desenlace obligatorio que permite conocer quién ganará el conflicto.'],['C097','C100'],'La atmósfera surge de recursos verbales y escénicos que se interpretan conjuntamente.')
micro(L,'Dos compañías representan el mismo diálogo con luces y gestos diferentes. ¿Qué relación se observa?', ['Un texto dramático admite distintas puestas en escena.','Cada representación elimina el conflicto escrito por el autor.','La obra teatral es siempre idéntica al texto y no incorpora interpretación.','Cambiar la luz convierte necesariamente el diálogo en una noticia.'],['C084','C098','C099'],'La realización escénica interpreta posibilidades del texto mediante decisiones propias.')
micro(L,'Un afiche invita a cuidar las bibliotecas públicas sin vender productos. ¿Qué finalidad predomina?', ['Propaganda social.','Publicidad comercial de una marca de libros que busca vender ejemplares.','Reportaje que contrasta varias fuentes para investigar los horarios.','Crónica que relata de manera documentada una jornada ya terminada.'],['C142'],'Busca promover una conducta colectiva y no una transacción comercial.')
micro(L,'Una cifra se destaca con gran tamaño y otra condición aparece en letra casi ilegible. ¿Qué conviene evaluar?', ['La jerarquía visual y lo que deja en segundo plano.','Solo la cantidad de colores, porque no influye la distribución del mensaje.','Únicamente si la cifra grande coincide con las preferencias personales del lector.','El prestigio de la imprenta como prueba suficiente de la conclusión del afiche.'],['C144'],'Tamaño y distribución pueden orientar atención y ocultar condiciones relevantes.')
micro(L,'Una noticia afirma «aumentaron los préstamos», pero no indica período ni base de comparación. ¿Qué falta?', ['Información para dimensionar el aumento.','Una opinión de una celebridad que confirme que todos leen cada día.','Una fotografía decorativa que sustituya los registros de préstamo.','Un adjetivo más enfático que convierta la afirmación en una conclusión causal.'],['C147'],'Sin período, cantidades y comparación no se puede estimar la magnitud ni el alcance.')
micro(L,'Dos medios seleccionan aspectos distintos del mismo acuerdo. ¿Qué concepto ayuda a analizar esa orientación?', ['Línea editorial.','Rima asonante que se produce entre dos titulares de distinta extensión.','Tiempo de la historia que determina la duración de una escena teatral.','Narrador testigo que participa como personaje dentro de ambos medios.'],['C145'],'La selección y jerarquización del tema puede relacionarse con la orientación del medio.')
micro(L,'Para conocer el horario vigente de una biblioteca, ¿qué fuente conviene consultar primero?', ['El horario oficial actualizado de esa biblioteca.','Un comentario antiguo sobre otra biblioteca ubicada en una ciudad diferente.','Una fotografía sin fecha donde se ve una puerta abierta durante una ceremonia.','Una encuesta de preferencias que no pregunta por las horas reales de atención.'],['C222','C223','C224'],'La fuente es pertinente para la pregunta y permite comprobar fecha e institución.')
micro(L,'Un gráfico compara préstamos mensuales. ¿Qué debe revisarse antes de afirmar que una diferencia es enorme?', ['Escala, unidades y cantidades representadas.','Solo el color más intenso usado para dibujar una de las barras.','La popularidad de la persona que compartió por primera vez la imagen.','La cantidad de comentarios que celebran la conclusión sin revisar sus datos.'],['C139','C236'],'Las decisiones de escala y unidades condicionan la magnitud que percibe el lector.')
t=text(L,'Antes de abrir','Escena dramática',[
'(Sala de una biblioteca. Dos sillas, un balde bajo una gotera y una puerta cerrada. MARTA coloca un cartel. LEO sostiene una carpeta.)\nLEO: Afuera esperan seis personas. Les dijimos que hoy podrían entrar.\nMARTA: Yo también quiero abrir. Pero la gotera está sobre el enchufe. No puedo prometer seguridad mirando hacia otro lado.\nLEO: Pensarán que inventamos otra excusa.\nMARTA: Podemos explicar lo que ocurre y ofrecer la mesa del pasillo mientras revisan la instalación.',
'LEO: (Aparta el balde del paso.) Si abrimos esa mesa, ¿quién entregará los libros?\nMARTA: Yo los llevaré. Tú puedes preguntar qué necesitan y ordenar la espera.\nLEO: (Aparte.) Temía que volver a preguntar fuera molestar.\nMARTA: ¿Qué dijiste?\nLEO: Que voy a preguntar. (Se dirige a la puerta; se detiene.) ¿Y si quieren todos el mismo libro?\nMARTA: Entonces tendremos otra pregunta que resolver. No hace falta saberlo todo para empezar, pero sí decir qué podemos hacer.',
'(MARTA sale hacia el depósito. LEO queda solo.)\nLEO: Yo quería una puerta abierta para demostrar que teníamos razón. Ella me pide una explicación. Quizás eso cuesta más: salir y decir que el plan cambió sin culpar a los que esperan. Si oculto la gotera, mañana desconfiarán también de las cosas que sí cumplimos. (Retira del cartel la frase «Acceso completo». Escribe «Atención en el pasillo». Se oye una conversación al otro lado.)',
'MARTA: (Regresa con tres libros.) ¿Vamos?\nLEO: Sí. Pero primero les cuento por qué.\n(MARTA deja los libros sobre una silla y abre la puerta. La luz del pasillo ilumina el balde. Ninguno intenta esconderlo.)'
])
question(L,t['questions'],'¿Qué conflicto central desarrolla la escena?', ['Cumplir el acceso prometido sin ocultar una condición insegura.','Impedir para siempre que las personas soliciten libros de la biblioteca.','Elegir qué personaje debe abandonar la lectura para dedicarse a reparar enchufes.','Resolver una rivalidad personal entre dos personajes que desean cerrar la sala.'],evidence='«Yo también quiero abrir»; «No puedo prometer seguridad mirando hacia otro lado».',reason='Ambos desean atender; la tensión está en cómo hacerlo responsablemente ante la filtración.',concepts=['C085','C086','C088'])
question(L,t['questions'],'¿Qué diferencia cumplen el aparte y el monólogo de Leo?', ['El aparte revela brevemente un temor y el monólogo desarrolla su revisión.','El aparte explica un pensamiento de Marta y el monólogo informa a toda la fila.','Ambos son instrucciones del autor que ningún actor debe pronunciar durante la obra.','Ambos confirman que Leo conoce lo que piensan todas las personas del pasillo.'],evidence='«Temía que [...] fuera molestar»; «Yo quería una puerta abierta [...]».',reason='El aparte comunica un temor que Marta no oye; el monólogo con Leo solo amplía su reflexión y cambio.',concepts=['C094','C093'])
question(L,t['questions'],'¿Qué cambio de Leo queda demostrado por una acción?', ['Modifica el cartel para ajustar la promesa a lo que pueden ofrecer.','Esconde el balde para que nadie advierta la filtración sobre el enchufe.','Entrega todos los libros sin explicar a los visitantes por qué cambió el plan.','Culpa a quienes esperan para justificar que la biblioteca no los atienda nunca.'],evidence='Retira «Acceso completo» y escribe «Atención en el pasillo».',reason='La corrección visible materializa la decisión de comunicar límites y actuar con transparencia.',concepts=['C090','C096','C017'])
question(L,t['questions'],'¿Qué efecto puede producir la luz final sobre el balde, según el conjunto?', ['Hacer visible el problema que los personajes deciden no ocultar.','Demostrar que la filtración desapareció antes de abrir la puerta.','Reemplazar las palabras del diálogo por una voz narrativa externa.','Asegurar que toda persona del público interpretará la escena de forma idéntica.'],skill='Evaluar',evidence='«La luz [...] ilumina el balde. Ninguno intenta esconderlo».',reason='La acotación relaciona una decisión visual con el cambio de los personajes; no garantiza una reacción única del público.',concepts=['C100','C099','C095'])
t=text(L,'La sala vacía y los datos que faltaban','Reportaje',[
'Una fotografía de la biblioteca comunitaria sin visitantes circuló acompañada por el titular «El barrio dejó de leer». La imagen había sido tomada a las siete y media de la mañana, media hora antes de abrir. Ese dato no aparecía en la primera publicación. La foto era auténtica, pero su uso permitía sugerir una conclusión que el instante registrado no podía sostener.',
'La encargada mostró el registro de préstamos de dos meses: ochenta en octubre y cien en noviembre. También explicó que la sala había abierto veinte días en octubre y veinticinco en noviembre. La cifra mensual aumentó, pero el promedio fue de cuatro préstamos por día de apertura en ambos meses. Ese promedio no informa cuántas personas distintas asistieron ni cuánto leyeron: un usuario pudo retirar varios libros y otros leer dentro de la sala sin pedir préstamos.',
'Un segundo medio tituló «La biblioteca registra veinticinco por ciento más préstamos». La relación entre ochenta y cien era correcta, aunque el titular no mencionaba los días adicionales de atención. Un tercer mensaje anunció «El nuevo horario hizo leer más a todos». Esa afirmación agregó una causa no aislada y una generalización sobre personas que el registro no identificaba.',
'El equipo consultó además a dos usuarios y a una vecina que no utiliza el servicio. Los primeros valoraron la ampliación del horario. La vecina explicó que no conocía la colección y que el regreso desde su trabajo aún coincidía con el cierre. Los testimonios aportaron experiencias relevantes, pero tres personas no podían representar todas las situaciones del barrio.',
'La investigación dejó una pregunta acotada para el mes siguiente: qué barreras de acceso persisten entre quienes no usan la biblioteca. Propuso combinar horarios, registros de consulta y una indagación más amplia, explicando cómo se seleccionaría a los participantes. No se trataba de elegir entre una imagen favorable y otra desfavorable, sino de precisar qué pregunta respondía cada evidencia.'
])
question(L,t['questions'],'¿Qué antecedente debilita directamente la conclusión del primer titular?', ['La fotografía fue tomada antes de la apertura.','La imagen mostraba una sala con mesas y estantes para guardar libros.','La fotografía podía compartirse en más de un medio de comunicación.','La biblioteca había registrado préstamos durante dos meses del mismo año.'],skill='Localizar',evidence='«media hora antes de abrir».',reason='El momento de captura explica la sala vacía sin permitir inferir desinterés general.',concepts=['C141','C147'])
question(L,t['questions'],'¿Qué comparación considera los días de funcionamiento?', ['En ambos meses hubo cuatro préstamos por día de apertura.','En noviembre todas las personas del barrio leyeron una cuarta parte más.','La biblioteca recibió exactamente veinte lectores distintos durante octubre.','El aumento de préstamos demuestra que el nuevo horario fue su única causa.'],evidence='80/20 = 4; 100/25 = 4, según los registros descritos.',reason='La comparación incorpora la base temporal y distingue préstamos de personas y lectura.',concepts=['C139','C147','C236'])
question(L,t['questions'],'¿Qué límite comparten los testimonios reunidos?', ['No representan por sí solos todas las experiencias del barrio.','Imposibilitan conocer cualquier dificultad particular de las personas consultadas.','Demuestran que la colección carece de interés para todos los habitantes de la comuna.','Sustituyen los registros y permiten conocer cuántos libros leyó cada vecino durante un año.'],evidence='«tres personas no podían representar todas las situaciones».',reason='Los casos aportan experiencias, pero no sostienen una generalización de alcance total.',concepts=['C112','C223'])
question(L,t['questions'],'¿Qué decisión mejora la investigación propuesta al final?', ['Acotar la pregunta e integrar fuentes pertinentes con selección explicada.','Repetir la fotografía inicial para comprobar que todo el barrio dejó de leer.','Publicar únicamente los testimonios favorables y retirar los registros de apertura.','Usar el aumento mensual como prueba suficiente de una mejora causada por el horario.'],skill='Evaluar',evidence='«qué barreras [...] persisten»; «cómo se seleccionaría a los participantes».',reason='Se define qué se necesita saber y se relaciona la evidencia con la pregunta y su alcance.',concepts=['C220','C223','C225'])
t=text(L,'Una campaña y sus condiciones','Afiche y aviso informativo recreados',[
'AFICHE A. Título grande: «Una puerta abierta, muchas historias». Imagen: una puerta iluminada y varias manos que acercan libros. Mensaje: «Dona un libro en buen estado para ampliar la colección comunitaria». Pie legible: «Campaña de la biblioteca del barrio. Recepción: miércoles, de 16:00 a 18:00. Consulta antes de llevar textos escolares antiguos». No ofrece productos a la venta.',
'AVISO B. Encabezado: «Regala historias: colección de cuentos con 30 % de descuento». Imagen: tres cubiertas y el nombre de una librería. Condición visible: «Promoción solo para los títulos señalados, hasta agotar el stock disponible». Botón: «Comprar».',
'Para preparar una presentación del curso sobre ambos mensajes, un grupo decidió registrar emisor, fecha de consulta y condiciones. Usó imágenes de las piezas con su procedencia, explicó su finalidad y evitó afirmar que la campaña había tenido éxito: todavía no contaba con resultados. En el borrador, un comentario de otra pareja pidió ampliar el tamaño del horario del afiche para que se pudiera leer al proyectarlo.'
])
question(L,t['questions'],'¿Qué diferencia principal existe entre las finalidades de A y B?', ['A promueve una acción comunitaria y B una compra.','A vende libros usados y B informa resultados de una investigación independiente.','Ambos solicitan donaciones sin ofrecer productos ni promover transacciones comerciales.','Ambos documentan una campaña terminada mediante cifras verificadas de sus resultados.'],evidence='«Dona un libro» frente a «Comprar» y descuento de una librería.',reason='El afiche promueve una conducta social; el aviso ofrece una transacción comercial.',concepts=['C142','C143'])
question(L,t['questions'],'¿Qué interpretación de la imagen del afiche A se sostiene mejor?', ['Relaciona la participación de varias personas con ampliar el acceso a historias.','Prueba documentalmente cuántos libros recibió la biblioteca durante la campaña.','Garantiza que todas las donaciones serán aceptadas sin revisar su estado o tipo.','Demuestra que la puerta permanecerá abierta todos los días sin restricciones de horario.'],evidence='Varias manos acercan libros; «ampliar la colección comunitaria».',reason='La imagen construye una invitación colectiva, pero no acredita resultados ni elimina condiciones.',concepts=['C144','C140'])
question(L,t['questions'],'¿Por qué el grupo evita afirmar que la campaña fue exitosa?', ['Todavía no dispone de evidencia sobre sus resultados.','Un afiche social impide investigar cualquier efecto en una comunidad.','Las condiciones de recepción demuestran que ninguna persona podría participar.','La presencia de imágenes vuelve falsa toda información que se presente junto a ellas.'],evidence='«todavía no contaba con resultados».',reason='Distingue propósito de la campaña y efecto realmente comprobado.',concepts=['C146','C147','C225'])
question(L,t['questions'],'¿Qué mejora cumple la revisión del borrador?', ['Ajusta la legibilidad de un dato necesario para participar.','Cambia la fecha de recepción para hacerla coincidir con una preferencia del grupo.','Elimina las fuentes porque una imagen no necesita procedencia cuando se proyecta.','Sustituye la explicación oral por una captura donde las condiciones quedan ilegibles.'],skill='Evaluar',evidence='«ampliar el tamaño del horario [...] para que se pudiera leer».',reason='El comentario genera una modificación concreta que favorece propósito y audiencia.',concepts=['C235','C237','C228'])
