# Recorridos individuales: mismo foco, un estímulo breve, seis alternativas, audio y una pregunta a la vez.
GUIDED={}
GKEYS={}
def guided(n,title,genre,paragraphs,items):
    sid=LESSONS[n-1]['id'];g={'title':title,'genre':genre,'paragraphs':paragraphs,'source':'Texto original de Estudia CEST para esta práctica.','questions':[]}; GKEYS[sid]={}
    for i,(prompt,choices,reason,evidence) in enumerate(items,1):
        k=(i-1)%4; options=choices[-k:]+choices[:-k] if k else choices
        q={'id':f'g{i:02}','text':prompt,'options':options,'skill':'Interpretar','concepts':[]};g['questions'].append(q)
        GKEYS[sid][q['id']]={'key':'ABCD'[k],'reason':reason,'evidence':evidence,'skill':'Interpretar','distractors':{}}
    GUIDED[sid]=g
guided(1,'Una llave para recordar','Relato breve',[
'Yo atendía la ferretería cuando una mujer pidió copiar una llave. Pensé que quería abrir una puerta. Ella explicó que la casa ya no existía y que quería darle una copia a su hermano para recordar los días que habían vivido allí.',
'Al escucharla, entendí que la llave podía servir para conservar un recuerdo. Hice la copia y salí a devolverle la original, que había quedado sobre el mesón. No sabía todavía qué le diría al encontrarla.'
],[
 ('¿Quién cuenta el relato?',['Una persona que atiende la ferretería.','Un hermano que espera dentro de la casa.','Una mujer que nunca llega a pedir una copia.','Una voz que no participa en ningún hecho.'],'El yo atiende y realiza acciones en la historia.','«Yo atendía»'),
 ('¿Qué pensó primero la voz que narra?',['Que la llave abriría una puerta.','Que el hermano trabajaba en la ferretería.','Que la mujer quería comprar una casa nueva.','Que la original ya había sido devuelta.'],'La primera hipótesis se expresa antes de la explicación.','«Pensé que quería abrir una puerta»'),
 ('¿Para qué quería la mujer una copia?',['Para compartir un recuerdo con su hermano.','Para abrir otra vez la puerta de la casa que ya no existe.','Para cambiar la cerradura de la ferretería.','Para impedir que alguien recordara la casa.'],'La copia tiene un propósito afectivo.','«para recordar los días»'),
 ('¿Qué cambia al escuchar la explicación?',['La forma de entender para qué sirve la llave.','El oficio que tiene la persona que narra.','El lugar donde se encuentra la ferretería.','El número de hermanos de la visitante.'],'Cambia su interpretación del objeto.','«entendí que [...] conservar un recuerdo»'),
 ('¿Qué dato no conoce aún la voz al final?',['Qué le dirá a la mujer cuando la encuentre.','Que la llave original quedó sobre el mesón.','Que la casa de los hermanos ya no existe.','Que la visitante ha pedido hacer una copia.'],'La conversación final queda pendiente.','«No sabía todavía qué le diría»'),
 ('¿Qué explicación se apoya mejor en el relato?',['Un objeto puede conservar un valor aunque ya no abra una puerta.','Toda llave que no abre una puerta debe ser desechada inmediatamente.','La visitante quiere impedir que su hermano recuerde su casa.','La ferretería permite reconstruir de inmediato cualquier casa perdida.'],'La función afectiva se sostiene por la explicación de la mujer.','«conservar un recuerdo»')])
guided(2,'La ventana','Poema breve',[
'La casa se quedó sin voz\ncuando partiste.\nHoy abrí una ventana\ny entró una risa de la calle.\nNo era la tuya.\nDejé que se quedara.'
],[
 ('¿Qué situación se menciona al comienzo?',['La partida de alguien.','La venta de una casa nueva.','La llegada de una familia completa.','La reparación de una ventana rota.'],'La voz menciona una partida.','«cuando partiste»'),
 ('¿Por qué «La casa se quedó sin voz» es lenguaje figurado?',['Atribuye una voz a una casa.','Informa literalmente que un edificio tiene garganta humana.','Enumera los materiales utilizados para construir la casa.','Describe el ruido de una máquina que se acaba de reparar.'],'La personificación atribuye una cualidad humana.','«La casa [...] sin voz»'),
 ('¿Qué hace la voz del poema?',['Abre una ventana.','Cierra para siempre todas las puertas del barrio.','Busca comprar una casa en una calle diferente.','Pide que nadie vuelva a reír cerca de su ventana.'],'La acción está expresada en el poema.','«Hoy abrí una ventana»'),
 ('¿La risa pertenece necesariamente a la persona que partió?',['No: el poema distingue ambas voces.','Sí: toda risa que entra por una ventana es de la misma persona.','Sí: el poema afirma que la persona regresó a vivir en la casa.','No: porque el poema dice que ninguna persona puede reír.'],'La negación distingue la nueva presencia de la ausente.','«No era la tuya»'),
 ('¿Qué muestra «Dejé que se quedara»?',['Una apertura a una nueva presencia.','Una orden para expulsar a todas las personas de la calle.','Una certeza de que la casa fue vendida durante esa mañana.','Una explicación de cómo se fabricó la ventana de la casa.'],'La voz acepta la risa que llega.','Último verso'),
 ('¿Qué relación une el inicio y el final?',['La ausencia inicial da paso a una apertura sin borrar el recuerdo.','La alegría se mantiene idéntica y sin cambios desde la primera línea.','El texto explica un procedimiento de reparación doméstica.','La nueva risa prueba que la partida nunca ocurrió en la historia.'],'El cambio no niega la partida; modifica cómo la vive la voz.','«cuando partiste» / «Dejé que se quedara»')])
guided(3,'Una propuesta que necesita razones','Columna breve',[
'Propongo abrir la biblioteca durante un recreo a la semana. Algunas personas salen de inmediato a tomar el bus y no alcanzan a retirar libros por la tarde. Antes de hacerlo, debemos comprobar que exista un turno adulto autorizado.',
'Dos estudiantes dijeron que no usarían ese horario. Eso no demuestra que nadie lo necesite. Conviene consultar a más personas y revisar los registros. Al terminar un mes de prueba, podríamos comparar resultados y corregir el plan.'
],[
 ('¿Qué propone la voz del texto?',['Abrir la biblioteca durante un recreo semanal.','Cerrar todas las bibliotecas al terminar el mes.','Cambiar el recorrido de todos los buses de la ciudad.','Reemplazar a todo el personal por dos estudiantes.'],'Es la tesis inicial.','«Propongo abrir»'),
 ('¿Qué razón entrega para esa propuesta?',['Algunas personas deben salir temprano a tomar el bus.','Todas las personas del colegio rechazaron el horario actual.','Dos estudiantes demostraron que nadie necesita retirar libros.','La biblioteca ya tiene siempre todos los turnos disponibles.'],'La razón se relaciona con una barrera horaria.','«no alcanzan a retirar libros»'),
 ('¿Qué condición debe comprobarse antes de abrir?',['La disponibilidad de un turno adulto autorizado.','La aprobación automática de todas las preferencias personales.','Que se eliminen los registros de préstamo del mes anterior.','Que dos estudiantes representen a toda la comunidad escolar.'],'El texto condiciona la viabilidad a ese recurso.','«debemos comprobar»'),
 ('¿Por qué dos respuestas no prueban que nadie usaría el horario?',['No bastan para representar a todo el grupo.','Porque las opiniones de estudiantes nunca pueden escucharse.','Porque toda respuesta negativa debe eliminarse de una consulta.','Porque la propuesta ya fue aprobada sin necesidad de revisión.'],'La conclusión universal excede los casos.','«Eso no demuestra que nadie lo necesite»'),
 ('¿Qué información adicional propone reunir?',['Más consultas y registros de uso.','Solo una imagen decorativa de una puerta abierta.','Un ataque a quienes tienen una opinión diferente.','Una promesa de que jamás habrá dificultades para abrir.'],'Son fuentes para evaluar la necesidad y el plan.','«consultar a más personas y revisar los registros»'),
 ('¿Qué actitud frente a la propuesta muestra el cierre?',['Disposición a probarla y revisarla con resultados.','Certeza de que ninguna modificación será necesaria.','Rechazo a conocer qué ocurrió durante la prueba.','Interés en castigar a quienes no usan la biblioteca.'],'El plan es revisable según evidencia.','«comparar resultados y corregir el plan»')])
guided(4,'Una puerta con explicación','Escena breve',[
'(Una biblioteca. Hay un balde bajo una gotera.)\nLEO: Afuera esperan para entrar.\nMARTA: Quiero atenderlos, pero el agua cae cerca del enchufe. Podemos llevar los libros a la mesa del pasillo.\nLEO: (Aparte.) Me da miedo explicar que el plan cambió.\nMARTA: ¿Qué dijiste?\nLEO: Que voy a contarles lo que ocurre. (Cambia el cartel por «Atención en el pasillo».)'
],[
 ('¿Qué problema impide abrir la sala como estaba previsto?',['Una filtración cerca de un enchufe.','La ausencia de todos los libros de la biblioteca.','Una orden de cerrar para siempre el pasillo.','La decisión de que nadie del barrio puede leer.'],'Marta explicita el problema de seguridad.','«el agua cae cerca del enchufe»'),
 ('¿Qué propone Marta?',['Atender en una mesa del pasillo.','Esconder el balde para que nadie pregunte por la filtración.','Abrir la sala sin explicar que hay agua junto al enchufe.','Enviar a todas las personas a comprar libros a otro barrio.'],'Propone otra forma de atención.','«llevar los libros a la mesa del pasillo»'),
 ('¿Qué indica el texto entre paréntesis al comienzo?',['Cómo se presenta el espacio de la escena.','Una frase que Leo debe pronunciar al público como diálogo.','Una noticia externa sobre una biblioteca de otra ciudad.','La conclusión de un narrador que conoce el futuro de todos.'],'Es una acotación sobre el espacio.','«Una biblioteca. Hay un balde...»'),
 ('¿Qué comunica el aparte de Leo al público?',['Su temor a explicar el cambio del plan.','La certeza de que Marta puede oír todo lo que él piensa.','Una orden para que las personas abandonen la lectura.','Una explicación sobre cómo reparar el enchufe mojado.'],'Revela su interioridad sin ser oído por Marta según la convención.','«Me da miedo explicar»'),
 ('¿Qué acción muestra que Leo decide comunicar el cambio?',['Modifica el cartel de atención.','Rompe los libros que Marta quiere llevar al pasillo.','Se va sin responder ninguna pregunta de quienes esperan.','Esconde la gotera y promete acceso completo a la sala.'],'La acción hace visible la nueva información.','«Cambia el cartel»'),
 ('¿Qué interpretación del cambio de plan está respaldada?',['Se busca atender explicando un límite de seguridad.','Se intenta demostrar que a ninguna persona le interesa leer.','Se ha comprobado que toda biblioteca debe permanecer cerrada.','Se elimina la necesidad de hablar con quienes están esperando.'],'La alternativa conserva atención y transparencia.','Propuesta de Marta y respuesta final de Leo')])

